import{_ as o,o as a,c as e,a0 as r}from"./chunks/framework.Czf8PZMA.js";const u=JSON.parse('{"title":"可投用 SECTION 三件套","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sections.md","filePath":"guide/sections.md","lastUpdated":null}'),n={name:"guide/sections.md"};function d(i,t,s,l,h,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="可投用-section-三件套" tabindex="-1">可投用 SECTION 三件套 <a class="header-anchor" href="#可投用-section-三件套" aria-label="Permalink to &quot;可投用 SECTION 三件套&quot;">​</a></h1><blockquote><p>三份<strong>可直接投用</strong>的 MasterFormat 三段式完整条款，是「完整版 SPEC 框架」中已深化到可发合同的样板。其余 SECTION 照此模板展开。</p></blockquote><h2 id="三份样板" tabindex="-1">三份样板 <a class="header-anchor" href="#三份样板" aria-label="Permalink to &quot;三份样板&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SECTION</th><th>结构类型</th><th>内容亮点</th><th>页面</th></tr></thead><tbody><tr><td><strong>05 12 00</strong> 结构钢框架</td><td>钢结构</td><td>三段式 + 材料替换换算表(CN↔US) + 3 停点(HP-1/2/3)</td><td><a href="./07-section-steel">07</a></td></tr><tr><td><strong>13 34 23</strong> 预制结构(UHPC)</td><td>混凝土/UHPC</td><td>ESR-5874 适用矩阵 + 中美对应 + 3 停点</td><td><a href="./08-section-uhpc">08</a></td></tr><tr><td><strong>06 16 00</strong> 木覆面板</td><td>木结构</td><td>剪力连续性 + 火/烟封堵 + 3 停点</td><td><a href="./09-section-wood-sheathing">09</a></td></tr></tbody></table><h2 id="三部曲模板-通用写法" tabindex="-1">三部曲模板（通用写法） <a class="header-anchor" href="#三部曲模板-通用写法" aria-label="Permalink to &quot;三部曲模板（通用写法）&quot;">​</a></h2><p>每份 SECTION 均含：</p><ol><li><strong>Part 1 General</strong>：范围、引用文件（美标验收基准）、提交、QA、交货存储</li><li><strong>Part 2 Products</strong>：⭐材料替换换算表（US 基准 ↔ CN 对标）+ 材料/焊材/防腐</li><li><strong>Part 3 Execution</strong>：工厂/现场/连接/检验 → 3 个 Hold Point 表 → 验收汇总表（可进合同）</li></ol><h2 id="_3-个-hold-point-通用规则" tabindex="-1">3 个 Hold Point（通用规则） <a class="header-anchor" href="#_3-个-hold-point-通用规则" aria-label="Permalink to &quot;3 个 Hold Point（通用规则）&quot;">​</a></h2><ul><li><strong>HP-1 出厂前</strong>：材料证书/FAT/扭矩或强度 + insignia → 放行</li><li><strong>HP-2 现场就位前</strong>：基础交接、锚栓复核(±2mm)</li><li><strong>HP-3 连接后/隐蔽前</strong>：焊缝/强度/水密/防火/抗震 + NCR 关闭 + 三重放行</li></ul><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>把对应段落复制进项目 SPEC，填 <code>[待定]</code> 处即可发出；Part 2/3 验收项可进采购/合同。同一模板适用于其余 SECTION（见 <code>spec/divisions/*</code>）。</p>',11)])])}const P=o(n,[["render",d]]);export{u as __pageData,P as default};
